    need(['--handoff','--out','--workspace'].includes(args[i]) && !options.has(args[i]) &&
      typeof args[i+1] === 'string' && !args[i+1].startsWith('--'), 'WOO_BUYER_ARGUMENT_INVALID');
    options.set(args[i], args[i+1]);
